"use client";

/**
 * End card: the wordmark set huge across the frame, a hard cut to a close-up
 * of part of it, then a cut back to a calm card with a call to action and a
 * web address.
 *
 * Written by Better Design. Three shots, two hard cuts, no transitions: the
 * calm of the last shot is the payoff of the first two.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, useCurrentFrame } from "remotion";
import { easings, mix, pickFont, progress, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "600", "800"], subsets: ["latin"] });

/** The two cuts, in frames. */
const CLOSE_AT = 48;
const CALM_AT = 80;

const initialsOf = (name: string): string =>
  name.split(/\s+/).filter(Boolean).slice(0, 2).map((word) => word.charAt(0)).join("").toUpperCase() || "B";

export interface EndCardProps {
  /** The brand name, set huge and then as the lockup. */
  name?: string;
  /** The call to action on the button. */
  cta?: string;
  /** The web address under the button. */
  url?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

function Huge({ name, frame, color, size }: { name: string; frame: number; color: string; size: number }) {
  return (
    <div style={{ display: "flex", whiteSpace: "pre", fontSize: size, fontWeight: 800, letterSpacing: "-0.055em", lineHeight: 1, color }}>
      {frame >= 2 + name.length * 2 + 18
        ? name
        : Array.from(name).map((char, i) => {
        const t = easings.out(progress(frame, 2 + i * 2, 18));
        return (
          <span key={i} style={{ display: "inline-block", overflow: "hidden", padding: "0.04em 0.08em 0.14em", margin: "-0.04em -0.08em -0.14em" }}>
            <span style={{ display: "inline-block", transform: `translateY(${(1 - t) * 1.05}em)` }}>{char}</span>
          </span>
        );
      })}
    </div>
  );
}

/** A huge wordmark, a hard cut to a close-up, then a calm end card with a call to action. */
export function EndCard({
  name = "Your product",
  cta = "Start building today",
  url = "yourproduct.com",
  theme: themeOverride,
  font,
}: EndCardProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, INTER);
  const size = Math.min(440, 1780 / (Math.max(name.length, 1) * 0.56));

  if (frame < CLOSE_AT) {
    const push = easings.out(progress(frame, 0, CLOSE_AT));
    return (
      <AbsoluteFill style={{ background: theme.background, alignItems: "center", justifyContent: "center", fontFamily: family, overflow: "hidden" }}>
        <div style={{ transform: `scale(${1 + 0.05 * push})` }}>
          <Huge name={name} frame={frame} color={theme.foreground} size={size} />
        </div>
      </AbsoluteFill>
    );
  }

  if (frame < CALM_AT) {
    const local = frame - CLOSE_AT;
    const drift = easings.out(progress(local, 0, CALM_AT - CLOSE_AT));
    return (
      <AbsoluteFill style={{ background: theme.primary, alignItems: "center", justifyContent: "center", fontFamily: family, overflow: "hidden" }}>
        <div style={{ transformOrigin: "34% 56%", transform: `translateX(${-60 * drift}px) scale(${3.3 + 0.25 * drift})` }}>
          <Huge name={name} frame={Number.POSITIVE_INFINITY} color={theme.primaryForeground} size={size} />
        </div>
      </AbsoluteFill>
    );
  }

  const local = frame - CALM_AT;
  const rise = (at: number) => {
    const t = easings.out(progress(local, at, 20));
    return { opacity: t, transform: `translateY(${(1 - t) * 18}px)` };
  };

  return (
    <AbsoluteFill style={{ background: theme.background, alignItems: "center", justifyContent: "center", fontFamily: family }}>
      <AbsoluteFill style={{ background: `radial-gradient(ellipse 1000px 560px at 50% 50%, ${withAlpha(theme.primary, 0.07)}, ${withAlpha(theme.primary, 0)} 70%)` }} />
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 56 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 28, ...rise(2) }}>
          <div
            style={{
              width: 112,
              height: 112,
              borderRadius: 28,
              background: `linear-gradient(150deg, ${mix(theme.primary, theme.primaryForeground, 0.12)}, ${theme.primary})`,
              color: theme.primaryForeground,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontSize: 48,
              fontWeight: 800,
              letterSpacing: "-0.04em",
            }}
          >
            {initialsOf(name)}
          </div>
          <span style={{ fontSize: 88, fontWeight: 800, letterSpacing: "-0.05em", color: theme.foreground }}>{name}</span>
        </div>
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 28 }}>
          <div
            style={{
              ...rise(10),
              background: theme.primary,
              color: theme.primaryForeground,
              fontSize: 36,
              fontWeight: 600,
              letterSpacing: "-0.01em",
              padding: "26px 52px",
              borderRadius: 999,
              boxShadow: `0 20px 40px -18px ${withAlpha(theme.primary, 0.7)}`,
            }}
          >
            {cta}
          </div>
          <div style={{ ...rise(18), fontSize: 32, fontWeight: 500, color: theme.mutedForeground, letterSpacing: "-0.005em" }}>{url}</div>
        </div>
      </div>
    </AbsoluteFill>
  );
}
